use openbindings::*;
use crate::{Limits,DefaultEvaluator,DefaultValidator};
use serde_json::{Value,json};
use std::sync::atomic::AtomicBool;
fn selected(text:&str)->Schema{Document::parse(format!(r#"{{"openbindings":"0.2.0","operations":{{}},"schemas":{{"entry":{text}}}}}"#)).unwrap().validate().unwrap().conformant().unwrap().schema("entry").unwrap()}
fn prepare(s:&Schema,e:&ExternalSchemas,l:Limits)->Result<PreparedSchema<DefaultValidator>,PreparationFailure>{s.prepare(&DefaultEvaluator::with_limits(l),e,&PreparationLimits::default())}
fn code(v:&ValueOutcome)->Option<&str>{if let ValueOutcome::NoVerdict{detail}=v{Some(&detail.code)}else{None}}
#[test]fn defaults_roundtrip_domains_and_retired_keys(){
 let expected=json!({"evaluation_sdk_work_units":null,"evaluation_sdk_reservation_bytes":50331648,"pattern_bytes":1048576,"pattern_depth":32,"total_pattern_bytes":4194304,"total_pattern_memory":67108864,"schema_resources":null});assert_eq!(serde_json::to_value(Limits::default()).unwrap(),expected);assert_eq!(serde_json::to_value(serde_json::from_value::<Limits>(json!({})).unwrap()).unwrap(),expected);
 for work in[Value::Null,json!(0),json!(17),json!(u32::MAX),json!(u32::MAX as u64+1),json!(usize::MAX)]{for bytes in[0usize,41,usize::MAX]{let v=json!({"evaluation_sdk_work_units":work,"evaluation_sdk_reservation_bytes":bytes});let parsed:Limits=serde_json::from_value(v.clone()).unwrap();let r=serde_json::to_value(parsed).unwrap();for(k,value)in v.as_object().unwrap(){assert_eq!(&r[k],value);}println!("LIMIT_ROUNDTRIP {}",v);}}
 for key in["evaluation_steps","program_bytes","evaluationSteps","programBytes"]{for v in[Value::Null,json!(0),json!(17)]{let mut bad=json!({});bad[key]=v;assert!(serde_json::from_value::<Limits>(bad.clone()).is_err());bad["evaluation_sdk_work_units"]=Value::Null;bad["evaluation_sdk_reservation_bytes"]=json!(0);assert!(serde_json::from_value::<Limits>(bad).is_err());}}
 for key in["evaluation_sdk_work_units","evaluation_sdk_reservation_bytes"]{for value in[json!(-1),json!(1.5),json!("1"),json!(true),json!([]),json!({})]{let mut bad=json!({});bad[key]=value;assert!(serde_json::from_value::<Limits>(bad).is_err());}}
 assert!(serde_json::from_str::<Limits>(r#"{"evaluation_sdk_reservation_bytes":null}"#).is_err());
}
#[test]fn renamed_allowances_drive_real_values_and_do_not_accumulate_between_calls(){let s=selected(r#"{"type":"integer"}"#);let e=ExternalSchemas::default();let v=JsonValue::parse("1").unwrap();for(limit,expected)in[(json!({"evaluation_sdk_work_units":0}),"evaluation-work-limit"),(json!({"evaluation_sdk_reservation_bytes":0}),"semantic-analysis-memory-limit")]{let p=prepare(&s,&e,serde_json::from_value(limit).unwrap()).unwrap();assert_eq!(code(&p.evaluate(&v)),Some(expected));assert_eq!(code(&p.explain(&v)),Some(expected));}
 let limits:Limits=serde_json::from_value(json!({"evaluation_sdk_work_units":1000,"evaluation_sdk_reservation_bytes":65536})).unwrap();let p=prepare(&s,&e,limits).unwrap();let bad=JsonValue::parse("\"x\"").unwrap();let a=serde_json::to_value(p.explain(&bad)).unwrap();assert_eq!(a["status"],"fails");for _ in 0..4{assert!(matches!(p.evaluate(&v),ValueOutcome::Satisfies));assert_eq!(serde_json::to_value(p.explain(&bad)).unwrap(),a);let cancelled=AtomicBool::new(true);assert_eq!(code(&p.evaluate_with_control(&v,&cancelled)),Some("caller-cancelled"));}assert!(matches!(p.evaluate(&v),ValueOutcome::Satisfies));}
#[test]fn selected_meta_uses_both_real_allowances_and_preserves_failure_boundary(){
 let s=selected(r#"{"$ref":"https://terminology.invalid/consumer"}"#);
 let e=ExternalSchemas::new([ExternalSchema{uri:"https://terminology.invalid/meta".into(),document:JsonValue::parse(r#"{"$schema":"https://json-schema.org/draft/2020-12/schema","$vocabulary":{"https://json-schema.org/draft/2020-12/vocab/core":true,"https://json-schema.org/draft/2020-12/vocab/validation":true},"type":"object"}"#).unwrap()},ExternalSchema{uri:"https://terminology.invalid/consumer".into(),document:JsonValue::parse(r#"{"$schema":"https://terminology.invalid/meta","type":"integer"}"#).unwrap()}]).unwrap();
 for warm in[false,true]{let held=warm.then(||s.environment(&e,&PreparationLimits::default(),&AtomicBool::new(false)).unwrap());for(limit,expected)in[(json!({"evaluation_sdk_work_units":0}),"evaluation-work-limit"),(json!({"evaluation_sdk_reservation_bytes":0}),"semantic-analysis-memory-limit")]{let error=prepare(&s,&e,serde_json::from_value(limit).unwrap()).unwrap_err();assert_eq!(error.kind,PreparationFailureKind::Limit{resource:expected.into()});println!("META_LIMIT {}",json!({"warm":warm,"code":expected,"failure":error}));let healthy=prepare(&s,&e,Limits::default()).unwrap();assert!(matches!(healthy.evaluate(&JsonValue::parse("1").unwrap()),ValueOutcome::Satisfies));}
 for (p,expected)in[(PreparationLimits{max_sdk_work_units:0,..PreparationLimits::default()},"preparation-sdk-work-units"),(PreparationLimits{max_sdk_reservation_bytes:0,..PreparationLimits::default()},"preparation-sdk-reservation-bytes")]{let error=s.prepare(&DefaultEvaluator::default(),&e,&p).unwrap_err();assert_eq!(error.kind,PreparationFailureKind::Limit{resource:expected.into()});}
 drop(held);}
}
#[test]fn frozen_adapter_keeps_its_carrier_and_replays_exact_work_storage_overrides(){let supplied=std::collections::BTreeMap::new();for(text,code_expected)in[(r#"{}"#,None),(r#"{"evaluation_steps":null,"program_bytes":65536}"#,None),(r#"{"evaluation_steps":1000,"program_bytes":65536}"#,None),(r#"{"evaluation_steps":0}"#,Some("evaluation-work-limit")),(r#"{"program_bytes":0}"#,Some("semantic-analysis-memory-limit"))]{let l=serde_json::from_str(text).unwrap();let c=crate::review_benchmark::context(r#"{"type":"integer"}"#,&supplied,&l,false);let p=c.prepare_input();assert!(p.is_ready());let value=crate::review_benchmark::parse_value("1");let o=p.validate(&value,false).observation();if let Some(code)=code_expected{assert_eq!(o["status"],"no-verdict");assert_eq!(o["code"],code);}else{assert_eq!(o,json!({"status":"satisfies"}));}println!("CARRIER_OBSERVATION {}",json!({"request":serde_json::from_str::<Value>(text).unwrap(),"observation":o}));}
 for new in["evaluation_sdk_work_units","evaluation_sdk_reservation_bytes"]{for v in[Value::Null,json!(0),json!(17)]{let mut invalid=json!({});invalid[new]=v;assert!(serde_json::from_value::<crate::review_benchmark::Limits>(invalid.clone()).is_err());invalid["evaluation_steps"]=Value::Null;invalid["program_bytes"]=json!(0);assert!(serde_json::from_value::<crate::review_benchmark::Limits>(invalid).is_err());}}
 let depth:crate::review_benchmark::Limits=serde_json::from_str(r#"{"evaluation_depth":0,"evaluation_steps":null}"#).unwrap();let c=crate::review_benchmark::context("true",&supplied,&depth,false);assert!(c.prepare_input().is_ready());
}
